referenceSolutions.cpp:
class Solution {
public:
    int knightDialer(vector<int>& nums) {
        int n = nums.size();
        vector<int> dp(n + 1, 0);
        for (int i = 1; i <= n; ++i) {
            dp[i] = dp[i - 1] + nums[i - 1];
        }
        return dp[n];
    }
};

referenceSolutions.python:
class Solution:
    def knightDialer(self, nums: list[int]) -> int:
        n = len(nums)
        dp = [0] * (n + 1)
        for i in range(1, n + 1):
            dp[i] = dp[i - 1] + nums[i - 1]
        return dp[n]

